import fs from 'fs';
import { fatal } from '../utils/logger.js';

/**
 * Project config at the project root: `tgcloud.jsonc` (JSONC) or `tgcloud.json`
 * (strict JSON), one per project. In the `static` block, `source` is the build
 * output folder, relative to the project root; every other key is the serving
 * config, sent to the server verbatim and validated there. `$schema` is ignored.
 */
export const CONFIG_FILE = 'tgcloud.json';
export const CONFIG_FILE_JSONC = 'tgcloud.jsonc';

// The name to print in messages: the file the project has, else the default.
export function configFileName() {
  return fs.existsSync(CONFIG_FILE) && !fs.existsSync(CONFIG_FILE_JSONC) ? CONFIG_FILE : CONFIG_FILE_JSONC;
}

// Serving keys normalizeConfig() fills with defaults; unknown keys pass through.
const SERVING_KEYS = ['spa', 'immutable', 'headers', 'redirects'];

// Read the project config; `{ static: null }` when there is no file.
// `tolerant: true` returns that instead of failing on a malformed file.
export function loadProjectConfig({ tolerant = false } = {}) {
  const fail = (msg) => { if (tolerant) return null; fatal(msg); };
  const hasJson = fs.existsSync(CONFIG_FILE);
  const hasJsonc = fs.existsSync(CONFIG_FILE_JSONC);
  if (hasJson && hasJsonc) {
    return fail(`Both ${CONFIG_FILE} and ${CONFIG_FILE_JSONC} exist — keep one.`) ?? { static: null };
  }
  if (!hasJson && !hasJsonc) return { static: null };
  const file = hasJson ? CONFIG_FILE : CONFIG_FILE_JSONC;
  const text = fs.readFileSync(file, 'utf-8');
  let raw;
  try {
    raw = JSON.parse(hasJson ? text : stripJsonc(text));
  } catch (err) {
    // A comment or trailing comma in the strict file gets a rename hint.
    let hint = '';
    if (hasJson) {
      try { JSON.parse(stripJsonc(text)); hint = ` — comments and trailing commas are not allowed in ${CONFIG_FILE}; rename the file to ${CONFIG_FILE_JSONC} to use them.`; } catch { /* a real syntax error */ }
    }
    return fail(`${file}: ${hint ? 'not valid JSON' + hint : err.message}`) ?? { static: null };
  }
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return fail(`${file}: must be a JSON object`) ?? { static: null };
  }
  if (tolerant) {
    try { return { static: parseStatic(raw.static) }; } catch { return { static: null }; }
  }
  return { static: parseStatic(raw.static) };
}

// JSONC → JSON: drop comments and trailing commas outside of strings.
// Comments become spaces, so JSON.parse error positions stay correct.
export function stripJsonc(text) {
  let out = '';
  let i = 0;
  const n = text.length;
  let inString = false;
  while (i < n) {
    const ch = text[i];
    if (inString) {
      out += ch;
      if (ch === '\\') { out += text[i + 1] ?? ''; i += 2; continue; }
      if (ch === '"') inString = false;
      i++;
      continue;
    }
    if (ch === '"') { inString = true; out += ch; i++; continue; }
    if (ch === '/' && text[i + 1] === '/') {
      while (i < n && text[i] !== '\n') { out += ' '; i++; }
      continue;
    }
    if (ch === '/' && text[i + 1] === '*') {
      const end = text.indexOf('*/', i + 2);
      const stop = end === -1 ? n : end + 2;
      for (; i < stop; i++) out += text[i] === '\n' ? '\n' : ' ';
      continue;
    }
    out += ch;
    i++;
  }
  // Trailing commas; the first alternative matches strings so they stay verbatim.
  return out.replace(/("(?:[^"\\]|\\.)*")|,(\s*[}\]])/g, (m, str, close) => str ?? close);
}

/**
 * Normalize the `static` block.
 *   absent/undefined → null (not managed)
 *   false            → { remove: true }
 *   "dist"           → { source: 'dist', config: {} }
 *   { source, ...serving } → { source, config: serving }
 */
export function parseStatic(value) {
  if (value === undefined || value === null) return null;
  if (value === false) return { remove: true };
  if (typeof value === 'string') return { source: requireSource(value), config: {} };
  if (typeof value !== 'object' || Array.isArray(value)) {
    fatal(`${configFileName()}: "static" must be a folder name, an object, or false`);
  }
  const { source, build, ...config } = value;
  if (build !== undefined) {
    fatal(`${configFileName()}: "static.build" is not supported yet — run your build, then push.`);
  }
  return { source: requireSource(source), config };
}

function requireSource(source) {
  if (typeof source !== 'string' || !source.trim()) {
    fatal(`${configFileName()}: "static.source" must name the build output folder (e.g. "dist")`);
  }
  const s = source.replace(/\\/g, '/').replace(/\/+$/, '');
  if (!s || s.startsWith('/') || s.split('/').some((seg) => seg === '..' || seg === '.' || !seg)) {
    fatal(`${configFileName()}: "static.source" must be a folder inside the project (got "${source}")`);
  }
  return s;
}

/**
 * The server's normalization of a serving config: all four keys present with
 * defaults, each redirect as {from, to, status} with status defaulting to 301.
 * Unknown keys pass through untouched.
 */
export function normalizeConfig(config) {
  const c = config && typeof config === 'object' ? config : {};
  const out = {
    spa: c.spa === true,
    immutable: Array.isArray(c.immutable) ? [...c.immutable] : [],
    headers: Array.isArray(c.headers) ? c.headers.map((h) => ({ ...h })) : [],
    redirects: Array.isArray(c.redirects)
      ? c.redirects.map((r) => ({ from: r?.from, to: r?.to, status: r?.status ?? 301 }))
      : [],
  };
  for (const k of Object.keys(c)) if (!SERVING_KEYS.includes(k)) out[k] = c[k];
  return out;
}

/**
 * Whether two configs describe the same bundle: `immutable` and the keys of
 * each `headers[].set` are order-insensitive; rule order matters.
 */
export function sameConfig(a, b) {
  return canonical(a) === canonical(b);
}

function canonical(c) {
  const n = normalizeConfig(c);
  const sortedSet = (set) => Object.fromEntries(Object.keys(set || {}).sort().map((k) => [k, set[k]]));
  return JSON.stringify({
    ...n,
    immutable: [...n.immutable].sort(),
    headers: n.headers.map((h) => ({ path: h.path, set: sortedSet(h.set) })),
  });
}
